<div class="stats-grid"><?php foreach([['players','Assigned players','users'],['cosmetics','Available cosmetics','spark'],['feedback','Feedback to review','message'],['polls','Active polls','chart']] as [$key,$label,$icon]):?><a class="stat-card" href="<?=h(AdminDashboard::url($key==='cosmetics'?'cosmetics':$key))?>"><span class="stat-label"><?=h($label)?> <?=admin_icon($icon)?></span><strong><?=h(number_format($dashboard['counts'][$key]))?></strong><span class="stat-link">Open <?=h($key)?> <?=admin_icon('arrow')?></span></a><?php endforeach?></div>
<div class="section-heading"><div><h2>Your workspace</h2><p>Everything you need to keep Axial moving.</p></div></div>
<div class="shortcut-grid"><?php foreach(['cosmetics','feedback','polls','payments'] as $key):[$label,$description,$icon]=AdminDashboard::PAGES[$key];?><a id="<?=$key==='payments'?'paynow':h($key)?>" class="shortcut" href="<?=h(AdminDashboard::url($key))?>"><span class="icon-tile"><?=admin_icon($icon)?></span><h3><?=h($label)?></h3><p><?=h($description)?></p><span class="shortcut-arrow"><?=admin_icon('arrow')?></span></a><?php endforeach?></div>
<div class="two-column"><section class="panel"><div class="panel-heading"><h2>Recent feedback</h2><a href="<?=h(AdminDashboard::url('feedback'))?>">View all →</a></div><?php if(!$dashboard['recentFeedback']):?><div class="empty-state"><?=admin_icon('message')?><h3>A quiet inbox.</h3><p>Player feedback will appear here as it arrives.</p></div><?php endif?>
<?php foreach($dashboard['recentFeedback'] as $item):?><a class="activity-row" href="<?=h(AdminDashboard::url('feedback'))?>#feedback-<?=h((string)$item['id'])?>"><span class="activity-icon"><?=admin_icon('message')?></span><span><strong><?=h($item['username'])?></strong><small><?=h(ucfirst($item['category']).' · '.ucfirst($item['kind']))?> · <?=h(gmdate('d M, H:i',(int)$item['created_at']))?></small></span><span class="badge <?=$item['status']==='approved'?'success':'purple'?>"><?=h(ucfirst($item['status']))?></span></a><?php endforeach?></section>
<section class="panel"><div class="panel-heading"><h2>Latest polls</h2><a href="<?=h(AdminDashboard::url('polls'))?>">View all →</a></div><?php if(!$dashboard['recentPolls']):?><div class="empty-state"><?=admin_icon('chart')?><h3>Start a conversation.</h3><p>Create a poll and let your players decide.</p><a class="button" href="<?=h(AdminDashboard::url('polls'))?>">Create a poll</a></div><?php endif?>
<?php foreach($dashboard['recentPolls'] as $poll):$open=!(int)$poll['closed']&&(int)$poll['closes_at']>time();?><a class="activity-row" href="<?=h(AdminDashboard::url('polls'))?>#poll-<?=h((string)$poll['id'])?>"><span><strong><?=h($poll['question'])?></strong><small><?=h((string)$poll['votes'])?> votes · <?=h(gmdate('d M, H:i',(int)$poll['closes_at']))?></small></span><span class="badge <?=$open?'success':'muted'?>"><?=$open?'Open':'Ended'?></span></a><?php endforeach?></section></div>
